// Firebase background push handler
// Config is injected at build time via /firebase-sw-config.js (generated by Vite)
importScripts('https://www.gstatic.com/firebasejs/11.9.0/firebase-app-compat.js')
importScripts('https://www.gstatic.com/firebasejs/11.9.0/firebase-messaging-compat.js')

// Config loaded from the page via postMessage or from the inline __FIREBASE_SW_CONFIG global
self.addEventListener('message', (event) => {
  if (event.data?.type === 'FIREBASE_CONFIG') {
    initFirebase(event.data.config)
  }
})

let messagingInstance = null

function initFirebase(config) {
  if (messagingInstance) return
  if (!config?.apiKey) return
  try {
    const app = firebase.apps.length > 0
      ? firebase.apps[0]
      : firebase.initializeApp(config)
    messagingInstance = firebase.messaging(app)
    messagingInstance.onBackgroundMessage((payload) => {
      const title = payload.notification?.title ?? 'Sanctum Alert'
      const options = {
        body: payload.notification?.body ?? '',
        icon: '/favicon-512.png',
        badge: '/favicon.png',
        tag: payload.data?.type ? `${payload.data.orgId}:${payload.data.type}` : 'sanctum-alert',
        renotify: true,
        data: payload.data ?? {},
      }
      self.registration.showNotification(title, options)
    })
  } catch (e) {
    console.warn('[firebase-sw] init failed:', e)
  }
}

self.addEventListener('notificationclick', (event) => {
  event.notification.close()
  const url = event.notification.data?.link ?? '/'
  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true }).then((windowClients) => {
      for (const client of windowClients) {
        if ('focus' in client) return client.focus()
      }
      return clients.openWindow(url)
    })
  )
})
